SYSTEM_FIELDS = [k for k, v in DATA_MODEL.items() if v.get("source") == "system"]


def field_destination(canonical: str) -> tuple[str, str]:
    """Return (table, column) for a canonical field name."""
    meta = DATA_MODEL[canonical]
    return meta["table"], meta["column"]


def group_spec_by_table(spec: dict[str, str]) -> dict[str, dict[str, str]]:
    """Re-key {canonical: source_column} into {table: {column: source_column}}."""
    by_table: dict[str, dict[str, str]] = {}
    for canonical, source in spec.items():
        if canonical not in DATA_MODEL:
            continue
        t, c = field_destination(canonical)
        by_table.setdefault(t, {})[c] = source
    return by_table
